]$photos$;
  f record;
  n int;
  sid uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.spots WHERE created_by_user_id IS NULL) THEN
    RAISE NOTICE 'spot_photos_302 batch1: マスタの寺社が無いので何もしない';
    RETURN;
  END IF;

  FOR f IN SELECT * FROM jsonb_to_recordset(photos) AS x(name text, prefecture text, r2_key text, width int, height int, focus_y real, author text, license text, license_url text, source_url text, is_cropped boolean, status text)
  LOOP
    SELECT count(*), min(s.id::text)::uuid INTO n, sid
      FROM public.spots s
     WHERE s.name = f.name AND s.prefecture = f.prefecture AND s.created_by_user_id IS NULL;
    IF n <> 1 THEN
      RAISE EXCEPTION 'spot_photos_302 batch1: %（%）: 名前と都道府県で % 行（1 行のはず）', f.name, f.prefecture, n;
    END IF;
    INSERT INTO public.spot_photos
      (spot_id, r2_key, width, height, focus_y, author, license, license_url, source_url, is_cropped, status)
    VALUES
      (sid, f.r2_key, f.width, f.height, f.focus_y, f.author, f.license, f.license_url, f.source_url, f.is_cropped, f.status)
    ON CONFLICT (spot_id) DO UPDATE SET
      r2_key = EXCLUDED.r2_key,
      width = EXCLUDED.width,
      height = EXCLUDED.height,
      focus_y = EXCLUDED.focus_y,
      author = EXCLUDED.author,
      license = EXCLUDED.license,
      license_url = EXCLUDED.license_url,
      source_url = EXCLUDED.source_url,
      is_cropped = EXCLUDED.is_cropped,
      status = EXCLUDED.status;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN
      RAISE EXCEPTION 'spot_photos_302 batch1: %（%）: 入ったのが % 行（1 行のはず）', f.name, f.prefecture, n;
    END IF;
  END LOOP;
END
$spot_photos_302$;
